        : results.All(r => r is CheckResult.Pass) && band == RiskBand.Low ? ("AUTO_APPROVE", [])
        : ("MANUAL_REVIEW", results.OfType<CheckResult.Refer>().Select(f => f.Reason).Append("risk:" + band).ToArray());
