public sealed class RoomTypeInventory
{
    public HotelId Hotel { get; }
    public RoomTypeId RoomType { get; }
    public DateOnly Night { get; }
    public int Total { get; private set; }
    public int Sold { get; private set; }
    public int Held { get; private set; }
    public int OverbookingAllowance { get; private set; }
    public byte[] RowVersion { get; private set; } = [];        // optimistic concurrency

    public int Available => Total + OverbookingAllowance - Sold - Held;
    public bool TryHold(int qty) { if (qty <= 0 || Available < qty) return false; Held += qty; return true; }
    public void ConfirmHold(int qty) { Held -= qty; Sold += qty; }
    public void ReleaseHold(int qty) => Held = Math.Max(0, Held - qty);
    public void Cancel(int qty) => Sold = Math.Max(0, Sold - qty);
}

public sealed class BookingService(HotelDb db, IPaymentGateway payments, TimeProvider clock)
{
    public async Task<Result<HoldId>> HoldAsync(HotelId hotel, RoomTypeId type, DateOnly from, DateOnly to, int qty, CancellationToken ct)
    {
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        var nights = await db.Inventory
            .Where(i => i.Hotel == hotel && i.RoomType == type && i.Night >= from && i.Night < to)
            .OrderBy(i => i.Night)                                  // consistent order avoids deadlocks
            .ToListAsync(ct);
        if (nights.Count != to.DayNumber - from.DayNumber || !nights.All(n => n.TryHold(qty)))
            return Result<HoldId>.Fail(new("no_availability", "Not available for all nights"));

        var hold = new Hold(HoldId.New(), hotel, type, from, to, qty, expiresAt: clock.GetUtcNow().AddMinutes(10));
        db.Holds.Add(hold);
        await db.SaveChangesAsync(ct);                              // RowVersion conflicts -> retry the whole hold
        await tx.CommitAsync(ct);
        return Result<HoldId>.Ok(hold.Id);
    }
}
