~~~csharp
public enum BreakerState { Closed, Open, HalfOpen }

public sealed class CircuitBreaker(CircuitBreakerOptions o, TimeProvider clock, ICircuitBreakerEvents events)
{
    private int _state = (int)BreakerState.Closed;
    private long _openedAtTicks;
    private int _halfOpenPermits;
    private readonly SlidingWindow _window = new(o.WindowBuckets, o.BucketDuration, clock);

    public BreakerState State => (BreakerState)Volatile.Read(ref _state);

    public async Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct)
    {
        if (!TryAcquire()) throw new BrokenCircuitException();
        try
        {
            var result = await action(ct);
            OnSuccess();
            return result;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested) { ReleaseProbe(); throw; }   // caller cancelled: not a failure
        catch (Exception ex) when (o.IsFailure(ex)) { OnFailure(); throw; }
    }

    private bool TryAcquire()
    {
        switch (State)
        {
            case BreakerState.Closed: return true;
            case BreakerState.Open:
                if (clock.GetUtcNow().UtcTicks - Interlocked.Read(ref _openedAtTicks) < o.BreakDuration.Ticks) return false;
                if (Interlocked.CompareExchange(ref _state, (int)BreakerState.HalfOpen, (int)BreakerState.Open) == (int)BreakerState.Open)
                { Volatile.Write(ref _halfOpenPermits, o.HalfOpenProbes); events.OnHalfOpened(); }
                goto case BreakerState.HalfOpen;
            case BreakerState.HalfOpen:
                return Interlocked.Decrement(ref _halfOpenPermits) >= 0;           // exactly N probes
            default: return false;
        }
    }

    private void OnSuccess()
    {
        _window.RecordSuccess();
        if (Interlocked.CompareExchange(ref _state, (int)BreakerState.Closed, (int)BreakerState.HalfOpen) == (int)BreakerState.HalfOpen)
        { _window.Reset(); events.OnClosed(); }
    }

    private void OnFailure()
    {
        _window.RecordFailure();
        var s = State;
        if (s == BreakerState.HalfOpen || (s == BreakerState.Closed && _window.Total >= o.MinimumThroughput && _window.FailureRatio >= o.FailureRatio))
            if (Interlocked.CompareExchange(ref _state, (int)BreakerState.Open, (int)s) == (int)s)
            { Interlocked.Exchange(ref _openedAtTicks, clock.GetUtcNow().UtcTicks); events.OnOpened(_window.FailureRatio); }
    }

    private void ReleaseProbe() { if (State == BreakerState.HalfOpen) Interlocked.Increment(ref _halfOpenPermits); }
}
