~~~csharp
public sealed class Store : IAsyncDisposable
{
    private readonly WriteAheadLog _wal;
    private MemTable _active = new();
    private MemTable? _flushing;
    private readonly Manifest _manifest;
    private readonly Lock _writeGate = new();

    public async ValueTask PutAsync(ReadOnlyMemory<byte> key, ReadOnlyMemory<byte> value, CancellationToken ct)
    {
        await _wal.AppendAsync(WalRecord.Put(key, value), ct);       // durable first (fsync per policy)
        lock (_writeGate)
        {
            _active.Put(key, value);
            if (_active.SizeBytes > Options.MemTableLimit) RotateMemTable();   // freeze and schedule flush
        }
    }

    public ValueTask DeleteAsync(ReadOnlyMemory<byte> key, CancellationToken ct) => PutTombstoneAsync(key, ct);

    public bool TryGet(ReadOnlySpan<byte> key, out byte[]? value)
    {
        if (_active.TryGet(key, out value, out var deleted)) return !deleted;
        if (_flushing?.TryGet(key, out value, out deleted) == true) return !deleted;
        foreach (var table in _manifest.TablesNewestFirst())
        {
            if (!table.Bloom.MightContain(key)) continue;            // skip most files cheaply
            if (table.TryGet(key, out value, out deleted)) return !deleted;
        }
        value = null; return false;
    }

    private void RotateMemTable()
    {
        _flushing = _active; _active = new MemTable();
        _ = Task.Run(async () =>
        {
            var file = await SsTableWriter.WriteAsync(_flushing!, Options.Directory);   // sorted, indexed, checksummed
            _manifest.AddLevel0(file);                                                // atomic manifest update
            await _wal.TruncateUpToAsync(_flushing!.LastSequence);
            _flushing = null;
        });
    }
    // DisposeAsync: flush, close WAL; startup: Manifest.Load + WAL replay
}
